"""Task-local inspection helper: locate SQLite database(s) in this folder and print their schema.

Read-only: opens any candidate database with sqlite3 in read-only URI mode and never writes.
"""
import os
import sqlite3
import sys

CANDIDATE_SUFFIXES = (".db", ".sqlite", ".sqlite3", ".sql3", ".db3")


def main() -> None:
    folder = os.path.dirname(os.path.abspath(__file__))
    print(f"Scanning folder: {folder}")
    entries = sorted(os.listdir(folder))
    print("Directory entries:")
    for entry in entries:
        full = os.path.join(folder, entry)
        kind = "dir" if os.path.isdir(full) else "file"
        size = os.path.getsize(full) if os.path.isfile(full) else "-"
        print(f"  [{kind}] {entry}  (size={size})")

    candidates = [
        os.path.join(folder, entry)
        for entry in entries
        if os.path.isfile(os.path.join(folder, entry))
        and entry.lower().endswith(CANDIDATE_SUFFIXES)
    ]

    if not candidates:
        print("\nNo candidate SQLite database files found by suffix.")
        # Fall back: sniff file headers of all files for the SQLite magic string.
        for entry in entries:
            full = os.path.join(folder, entry)
            if os.path.isfile(full):
                try:
                    with open(full, "rb") as fh:
                        head = fh.read(16)
                    if head.startswith(b"SQLite format 3\x00"):
                        candidates.append(full)
                        print(f"  Sniffed SQLite header in: {entry}")
                except OSError as exc:
                    print(f"  Could not read {entry}: {exc}")

    for path in candidates:
        print(f"\n=== Database: {os.path.basename(path)} ===")
        uri = f"file:{path}?mode=ro"
        try:
            with sqlite3.connect(uri, uri=True) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.cursor()
                cur.execute("PRAGMA query_only = ON")
                tables = [
                    row["name"]
                    for row in cur.execute(
                        "SELECT name FROM sqlite_master "
                        "WHERE type IN ('table', 'view') AND name NOT LIKE 'sqlite_%' "
                        "ORDER BY name"
                    ).fetchall()
                ]
                print(f"Tables/views: {tables}")
                for table in tables:
                    print(f"\n-- schema for {table} --")
                    for row in cur.execute(
                        "SELECT sql FROM sqlite_master WHERE name = ?", (table,)
                    ).fetchall():
                        print(row["sql"])
                    print("-- columns --")
                    for col in cur.execute(f'PRAGMA table_info("{table}")').fetchall():
                        print(
                            f"  {col['name']}  {col['type']}  "
                            f"notnull={col['notnull']} default={col['dflt_value']!r} "
                            f"pk={col['pk']}"
                        )
        except sqlite3.Error as exc:
            print(f"Error opening {path}: {exc}")

    print("\nInspection complete.")
    return 0


if __name__ == "__main__":
    sys.exit(main())

